<template>
  <div class="sso-callback">
    <van-loading size="24px" color="#fff" vertical>正在登录...</van-loading>
  </div>
</template>

<script>
import { larkExchange } from '@/api'

export default {
  name: 'SsoCallback',
  mounted() {
    const params = new URLSearchParams(location.hash.slice(1))
    const ticket = params.get('ticket')
    const error = params.get('error')
    // ticket 不能留在地址栏和历史记录里
    history.replaceState(history.state, '', location.pathname + location.search)
    if (error || !ticket) {
      this.fail(error || 'ticket_missing')
      return
    }
    larkExchange(ticket).then(res => {
      if (!res?.token) {
        this.fail('token_missing')
        return
      }
      this.$store.commit('setToken', res.token)
      this.$store.commit('setUserInfo', { user_name: res.user_name, role: res.role || 1 })
      this.$notify({ type: 'success', message: '登录成功' })
      this.$router.replace(this.safeRedirect(res.redirect))
    }).catch(err => {
      this.fail(typeof err === 'string' ? err : 'server_error')
    })
  },
  methods: {
    // 只允许站内路径，防止 //evil.com 之类的跳转
    safeRedirect(redirect) {
      return typeof redirect === 'string' && redirect.startsWith('/') && !redirect.startsWith('//') ? redirect : '/'
    },
    fail(code) {
      this.$router.replace('/login?error=' + encodeURIComponent(code))
    }
  }
}
</script>

<style lang="scss" scoped>
.sso-callback {
  width: 100%;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #2c3254;
}
</style>
